def shortest_path(edges, start, end):
    """
    Find the shortest path in a directed graph using Dijkstra's algorithm.

    Args:
        edges: List of tuples (from_node, to_node, weight) representing one-way streets.
        start: Starting node.
        end: Ending node.

    Returns:
        Tuple of (distance, path) where distance is the total distance of the shortest path
        and path is a list of nodes along the path.
        If start == end, returns (0, [start]).
        If no route exists, returns (None, None).
        If any edge has negative weight, raises ValueError.
    """
    # Check for negative weights
    for edge in edges:
        if len(edge) != 3:
            raise ValueError(f"Each edge must be a tuple of (from_node, to_node, weight), got {edge}")
        if edge[2] < 0:
            raise ValueError("Negative edge weights are not allowed")

    # Handle case where start and end are the same
    if start == end:
        return (0, [start])

    # Build adjacency list
    graph = {}
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = []
        graph[from_node].append((to_node, weight))

    # Dijkstra's algorithm
    import heapq

    # Distances from start to each node
    distances = {start: 0}
    # Previous node on the shortest path
    previous = {}
    # Priority queue: (distance, node)
    pq = [(0, start)]
    visited = set()

    while pq:
        dist, node = heapq.heappop(pq)

        if node in visited:
            continue

        visited.add(node)

        # If we reached the end node, we can stop
        if node == end:
            break

        neighbors = graph.get(node, [])
        for neighbor, weight in neighbors:
            if neighbor in visited:
                continue
            new_dist = dist + weight
            if neighbor not in distances or new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                previous[neighbor] = node
                heapq.heappush(pq, (new_dist, neighbor))

    # Check if end was reached
    if end not in distances:
        return (None, None)

    # Reconstruct the path
    path = []
    current = end
    while current != start:
        path.append(current)
        current = previous[current]
    path.append(start)
    path.reverse()

    return (distances[end], path)
